CREATE OR REPLACE FUNCTION private.refresh_video_comment_stats_after_prediction_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  pairs jsonb;
begin
  select coalesce(
    jsonb_agg(jsonb_build_object(
      'workspace_id', touched.workspace_id,
      'video_id', touched.video_id
    )),
    '[]'::jsonb
  )
  into pairs
  from (
    select distinct changed.workspace_id, c.video_id
    from (
      select old_p.workspace_id, old_p.comment_id
      from old_predictions old_p
      join new_predictions new_p on new_p.id = old_p.id
      where old_p.status is distinct from new_p.status
      union
      select new_p.workspace_id, new_p.comment_id
      from new_predictions new_p
      join old_predictions old_p on old_p.id = new_p.id
      where old_p.status is distinct from new_p.status
    ) changed
    join public.comments c
      on c.workspace_id = changed.workspace_id
     and c.id = changed.comment_id
  ) touched;

  perform private.refresh_video_comment_stats(pairs);
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.register_channel_impl(w uuid, c uuid, external text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ch uuid; allowed int; begin
 if not private.has_role(w,array['workspace_owner','analyst']) then raise exception 'forbidden' using errcode='42501'; end if;
 if not exists(select 1 from public.clients where workspace_id=w and id=c) then raise exception 'invalid_client' using errcode='23503'; end if;
 if external !~ '^UC[A-Za-z0-9_-]{22}$' then raise exception 'invalid_channel_id' using errcode='22023'; end if;
 select id into ch from public.channels
 where workspace_id=w and platform='youtube' and external_channel_id=external and client_id=c;
 if ch is not null then return ch; end if;
 allowed := private.plan_limit(w,'channels');
 if allowed is not null
    and (select count(*) from public.channels chan join public.subscriptions sub on sub.workspace_id = chan.workspace_id
         where coalesce(sub.billing_workspace_id, sub.workspace_id) = private.billing_root(w)) >= allowed then
   raise exception 'channel_limit_reached' using errcode='53400'; end if;
 insert into public.channels(workspace_id,client_id,external_channel_id) values(w,c,external)
 on conflict(workspace_id,platform,external_channel_id) do nothing returning id into ch;
 if ch is null then raise exception 'channel_claimed_by_other_client' using errcode='23505'; end if;
 return ch;
end $function$

CREATE OR REPLACE FUNCTION private.register_platform_worker_credential(secret text, label text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare new_id uuid; begin
  if secret is null or length(secret) < 32 then
    raise exception 'weak_credential' using errcode='22023'; end if;
  insert into private.worker_credentials(token_hash, label, workspace_id)
  values (encode(extensions.digest(secret, 'sha256'), 'hex'), label, null)
  returning private.worker_credentials.id into new_id;
  return new_id;
end $function$

CREATE OR REPLACE FUNCTION private.register_public_channel_impl(w uuid, c uuid, external text, handle text, title text, p_platform text DEFAULT 'youtube'::text)
 RETURNS channels
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ch public.channels;
begin
  if not private.has_role(w, array['workspace_owner','analyst']) then
    raise exception 'forbidden' using errcode='42501';
  end if;
  if not exists (
    select 1
    from public.subscriptions s
    join public.plans p on p.key = s.plan_key
    where s.workspace_id = private.billing_root(w)
      and private.subscription_open(s)
      and (p.allow_public_channels or p.internal)
  ) then
    raise exception 'public_channels_not_allowed_on_plan' using errcode='53400';
  end if;
  if not exists(select 1 from public.clients where workspace_id=w and id=c) then
    raise exception 'invalid_client' using errcode='23503';
  end if;
  if p_platform not in ('youtube', 'telegram', 'x', 'tiktok', 'facebook', 'instagram') then
    raise exception 'invalid_platform' using errcode='22023';
  end if;
  if p_platform = 'youtube' then
    if external !~ '^UC[A-Za-z0-9_-]{22}$' then
      raise exception 'invalid_channel_id' using errcode='22023'; end if;
  elsif p_platform = 'telegram' then
    if external !~ '^(@?[A-Za-z0-9_]{4,64}|-?[0-9]+)$' then
      raise exception 'invalid_channel_id' using errcode='22023'; end if;
  elsif length(trim(external)) < 1 or length(external) > 100 then
    raise exception 'invalid_channel_id' using errcode='22023';
  end if;

  handle := nullif(trim(coalesce(handle, '')), '');
  title := nullif(trim(coalesce(title, '')), '');
  if handle is not null and length(handle) > 50 then
    raise exception 'invalid_channel_handle' using errcode='22023'; end if;
  if title is not null and length(title) > 200 then
    raise exception 'invalid_channel_title' using errcode='22023'; end if;

  insert into public.channels(workspace_id, client_id, external_channel_id, handle, title, platform)
  values (w, c, external, handle, title, p_platform)
  on conflict (workspace_id, platform, external_channel_id) do nothing
  returning * into ch;
  if ch.id is null then
    select * into ch from public.channels
     where workspace_id = w and platform = p_platform
       and external_channel_id = external and client_id = c;
    if ch.id is null then
      raise exception 'channel_claimed_by_other_client' using errcode='23505';
    end if;
  end if;

  perform private.adopt_channel_content(w, ch.id);
  return ch;
end $function$

CREATE OR REPLACE FUNCTION private.register_worker_credential(secret text, label text, w uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare new_id uuid; begin
  if secret is null or length(secret) < 32 then
    raise exception 'weak_credential' using errcode='22023'; end if;
  if not exists(select 1 from public.workspaces where id = w) then
    raise exception 'invalid_workspace' using errcode='23503'; end if;
  insert into private.worker_credentials(token_hash, label, workspace_id)
  values (encode(extensions.digest(secret, 'sha256'), 'hex'), label, w)
  returning private.worker_credentials.id into new_id;
  return new_id;
end $function$

CREATE OR REPLACE FUNCTION private.reject_review_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE'
     and current_setting('app.deleting_workspace', true) is not null
     and current_setting('app.deleting_workspace', true) = old.workspace_id::text then
    return old;
  end if;
  raise exception 'comment_reviews_is_append_only' using errcode='0A000';
end $function$

CREATE OR REPLACE FUNCTION private.release_usage(w uuid, keys text[])
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n int; begin
 -- A confirmed charge is history. Only an unused reservation is given back.
 delete from public.usage_events where workspace_id=w and event_key=any(keys) and state='reserved';
 get diagnostics n = row_count; return n;
end $function$

CREATE OR REPLACE FUNCTION private.remove_channel_impl(w uuid, c uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and not private.has_role(w, array['workspace_owner']) then
    raise exception 'forbidden' using errcode='42501';
  end if;
  if not exists(select 1 from public.channels where workspace_id=w and id=c) then
    raise exception 'invalid_channel' using errcode='23503';
  end if;

  perform set_config('app.deleting_workspace', w::text, true);

  delete from private.job_batches where job_id in (select id from public.jobs where workspace_id = w and channel_id = c);
  delete from public.jobs where workspace_id = w and channel_id = c;

  delete from public.sentiment_predictions where workspace_id = w and comment_id in (
    select c2.id from public.comments c2 join public.videos v on v.id = c2.video_id where v.workspace_id = w and v.channel_id = c
  );
  delete from public.topic_predictions where workspace_id = w and comment_id in (
    select c2.id from public.comments c2 join public.videos v on v.id = c2.video_id where v.workspace_id = w and v.channel_id = c
  );
  delete from public.comment_reviews where workspace_id = w and comment_id in (
    select c2.id from public.comments c2 join public.videos v on v.id = c2.video_id where v.workspace_id = w and v.channel_id = c
  );
  delete from public.topic_reviews where workspace_id = w and comment_id in (
    select c2.id from public.comments c2 join public.videos v on v.id = c2.video_id where v.workspace_id = w and v.channel_id = c
  );
  delete from public.comment_annotations where workspace_id = w and comment_id in (
    select c2.id from public.comments c2 join public.videos v on v.id = c2.video_id where v.workspace_id = w and v.channel_id = c
  );
  delete from public.comments where workspace_id = w and video_id in (
    select v.id from public.videos v where v.workspace_id = w and v.channel_id = c
  );
  delete from public.video_selections where workspace_id = w and channel_id = c;
  delete from public.videos where workspace_id = w and channel_id = c;
  delete from public.sync_runs where workspace_id = w and channel_id = c;
  delete from private.oauth_connections where workspace_id = w and channel_id = c;
  delete from public.channels where workspace_id = w and id = c;
end $function$

CREATE OR REPLACE FUNCTION private.request_discovery_impl(w uuid, c uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j uuid; gap int; begin
  if not private.has_role(w, array['workspace_owner','analyst']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  if not exists(select 1 from public.channels where workspace_id=w and id=c) then
    raise exception 'invalid_channel' using errcode='23503'; end if;
  select id into j from public.jobs
   where workspace_id=w and channel_id=c and type='discover'
     and status in ('queued','running') order by created_at limit 1;
  if j is not null then return j; end if;
  gap := private.plan_limit(w, 'sync_interval');
  if gap is not null and gap > 0 and exists(
       select 1 from public.jobs where workspace_id=w and channel_id=c and type='discover'
         and created_at > now() - make_interval(mins => gap)) then
    raise exception 'sync_too_soon' using errcode='53400'; end if;
  begin
    insert into public.jobs(workspace_id, channel_id, type, dedupe_key)
    values (w, c, 'discover', 'discover-' || gen_random_uuid()::text) returning id into j;
  exception when unique_violation then
    select id into j from public.jobs
     where workspace_id=w and channel_id=c and type='discover'
       and status in ('queued','running') order by created_at limit 1;
  end;
  return j;
end $function$

CREATE OR REPLACE FUNCTION private.reserve_usage(w uuid, kind text, keys text[])
 RETURNS text[]
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  sub record;
  allowance bigint;
  used bigint;
  covered text[];
  fresh text[];
begin
  if kind not in ('comment_analysis', 'historical_backfill', 'topic_classification') then
    raise exception 'invalid_event_type' using errcode='22023';
  end if;
  if coalesce(array_length(keys, 1), 0) > 500 then
    raise exception 'batch_too_large' using errcode='22023';
  end if;

  select private.subscription_open(s) as open, s.period_start,
         pl.analysis_units, pl.backfill_units, pl.topic_units
    into sub
    from public.subscriptions s join public.plans pl on pl.key = s.plan_key
   where s.workspace_id = private.billing_root(w) for update of s;
  if not found then raise exception 'no_active_plan' using errcode='42501'; end if;
  if not sub.open then raise exception 'plan_inactive' using errcode='42501'; end if;

  allowance := case kind
    when 'comment_analysis' then sub.analysis_units
    when 'historical_backfill' then sub.backfill_units
    else sub.topic_units
  end;

  select coalesce(array_agg(u.event_key), '{}') into covered
    from public.usage_events u
   where u.workspace_id = w and u.event_key = any(keys);

  select coalesce(array_agg(distinct k), '{}') into fresh
    from unnest(keys) as k
   where not (k = any(covered));

  if allowance is not null and allowance < 2147483647 then
    allowance := allowance + private.granted_units(w, kind);
    used := private.used_units(w, kind, sub.period_start);
    fresh := fresh[1:greatest(allowance - used, 0::bigint)];
  end if;

  insert into public.usage_events(workspace_id, period_start, event_key, event_type)
  select w, sub.period_start, k, kind from unnest(fresh) as k;

  return covered || fresh;
end $function$

CREATE OR REPLACE FUNCTION private.retire_platform_worker_credentials(keep uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer; begin
  if keep is null or cardinality(keep) = 0 then
    raise exception 'keep_at_least_one' using errcode='22023'; end if;
  if exists(select 1 from unnest(keep) k(id)
             where not exists(select 1 from private.worker_credentials c
                               where c.id = k.id and c.workspace_id is null and c.status = 'active')) then
    raise exception 'unknown_credential' using errcode='23503'; end if;
  update private.worker_credentials
     set status = 'revoked'
   where workspace_id is null and status = 'active' and not (id = any(keep));
  get diagnostics n = row_count;
  return n;
end $function$

CREATE OR REPLACE FUNCTION private.retire_worker_credentials(w uuid, keep uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer; begin
  if not exists(select 1 from public.workspaces where id = w) then
    raise exception 'invalid_workspace' using errcode='23503'; end if;
  keep := coalesce(keep, '{}'::uuid[]);
  if cardinality(keep) = 0
     and not exists(select 1 from private.worker_credentials c
                     where c.workspace_id is null and c.status = 'active') then
    raise exception 'keep_at_least_one' using errcode='22023'; end if;
  if exists(select 1 from unnest(keep) k(id)
             where not exists(select 1 from private.worker_credentials c
                               where c.id = k.id and c.workspace_id = w and c.status = 'active')) then
    raise exception 'unknown_credential' using errcode='23503'; end if;
  update private.worker_credentials
     set status = 'revoked'
   where workspace_id = w and status = 'active' and not (id = any(keep));
  get diagnostics n = row_count;
  return n;
end $function$

CREATE OR REPLACE FUNCTION private.retry_job_impl(w uuid, j uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current record; fresh uuid; begin
  if not private.has_role(w, array['workspace_owner','analyst']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  select status, channel_id, type, checkpoint into current
    from public.jobs where workspace_id=w and id=j;
  if not found then raise exception 'unknown_job' using errcode='42704'; end if;
  if current.status not in ('failed','blocked','cancelled','partial') then
    raise exception 'job_not_retryable' using errcode='53400'; end if;

  -- A new job rather than a reset one. The attempt that failed is part of the
  -- record: rewinding it would erase the evidence of what went wrong, which is
  -- exactly what somebody investigating a retry needs.
  --
  -- The checkpoint carries over, so a backfill that stopped halfway resumes
  -- instead of re-reading the channel from its first video.
  insert into public.jobs(workspace_id, channel_id, type, dedupe_key, checkpoint)
  values (w, current.channel_id, current.type,
          'retry:' || j::text || ':' || extract(epoch from now())::bigint::text,
          current.checkpoint)
  returning id into fresh;
  return fresh;
end $function$

CREATE OR REPLACE FUNCTION private.schedule_all()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid; begin
  for w in select workspace_id from public.subscriptions where status = 'active' loop
    perform private.schedule_due_work(w);
  end loop;
end $function$

CREATE OR REPLACE FUNCTION private.schedule_due_work(w uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ch record; d int := 0; k int := 0; a int := 0; cat int; begin
  -- Automatically unblock any blocked jobs whose wait duration elapsed
  perform private.unblock_due_jobs();

  cat := coalesce(private.plan_limit(w, 'catalogue_interval'), 1440);
  for ch in select id, catalogued_at from public.channels
             where workspace_id = w and status in ('connected', 'public_unverified') loop
    if ch.catalogued_at is null
       or ch.catalogued_at < now() - make_interval(mins => cat) then
      if private.enqueue_scheduled(w, ch.id, 'discover') is not null then d := d + 1; end if;
    end if;

    if private.has_due_videos(w, ch.id) then
      if private.enqueue_scheduled(w, ch.id, 'collect') is not null then k := k + 1; end if;
    end if;

    if private.topics_pending(w, ch.id) then
      if private.enqueue_scheduled(w, ch.id, 'analyse') is not null then a := a + 1; end if;
    end if;
  end loop;

  return jsonb_build_object('discover', d, 'collect', k, 'analyse', a);
end $function$

CREATE OR REPLACE FUNCTION private.seed_default_topics(w uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into public.workspace_topics(workspace_id, key, name_ar, name_en, description, position)
  values
    (w, 'question',   'استفسارات وأسئلة',           'Questions & inquiries',
        'Asks the creator or others something, or requests information.', 1),
    (w, 'religious',  'دعاء وذكر وتعبير ديني',      'Prayers & religious remarks',
        'Prayer, supplication, remembrance of God, religious phrasing as the main content.', 2),
    (w, 'praise',     'إشادة ودعم',                 'Praise & support',
        'Compliments, thanks, encouragement toward the creator or content.', 3),
    (w, 'criticism',  'نقد واعتراض',                'Criticism & objection',
        'Disagreement, complaint, or negative judgement of the content, creator or subject.', 4),
    (w, 'request',    'طلبات واقتراحات',            'Requests & suggestions',
        'Asks for future content, features, changes, or makes a suggestion.', 5),
    (w, 'discussion', 'نقاش وتحليل الموضوع',        'Discussion of the subject',
        'Substantive commentary on the topic of the video itself.', 6),
    (w, 'personal',   'تجارب وقصص شخصية',           'Personal stories & experiences',
        'Shares the commenter''s own situation or experience.', 7),
    (w, 'humour',     'مزاح ودعابة',                'Humour & banter',
        'Jokes, memes, playful remarks.', 8),
    (w, 'promotion',  'ترويج ومحتوى دعائي',         'Promotion & spam',
        'Advertising, self-promotion, links, repeated off-purpose content.', 9),
    (w, 'other',      'خارج الموضوع / أخرى',        'Off-topic / other',
        'Does not fit the above or is unrelated to the video.', 10)
  on conflict (workspace_id, key) do nothing;
$function$

CREATE OR REPLACE FUNCTION private.seed_topics_for_new_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.seed_default_topics(new.id);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.select_videos_impl(w uuid, c uuid, add uuid[], remove uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare estimate bigint := 0; unknowns int := 0; outstanding bigint := 0; remaining bigint; j uuid;
        queued boolean := false; deferred boolean := false; running boolean := false;
        rec record;
begin
  if not private.has_role(w, array['workspace_owner','analyst']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  if not exists(select 1 from public.channels where workspace_id=w and id=c) then
    raise exception 'invalid_channel' using errcode='23503'; end if;
  add := coalesce(add, '{}'::uuid[]); remove := coalesce(remove, '{}'::uuid[]);
  if exists(select 1 from unnest(add || remove) x(id)
             where not exists(select 1 from public.videos v
                               where v.workspace_id=w and v.channel_id=c and v.id=x.id)) then
    raise exception 'invalid_video' using errcode='23503'; end if;
  if exists(select 1 from public.videos v
             where v.workspace_id=w and v.id = any(add) and v.comments_state='disabled') then
    raise exception 'comments_disabled' using errcode='22023'; end if;

  -- Comments already in the database were already metered. A null count adds
  -- nothing to the sum and is reported apart, never as zero.
  select coalesce(sum(greatest(0, v.reported_comment_count
           - coalesce(stats.total, 0))), 0)::bigint,
         count(*) filter (where v.reported_comment_count is null)::int
    into estimate, unknowns
    from public.videos v
    left join private.video_comment_stats stats
      on stats.workspace_id=w and stats.video_id=v.id
   where v.workspace_id=w and v.id = any(add)
     and not exists(select 1 from public.video_selections s
                     where s.workspace_id=w and s.video_id=v.id);

  -- What is already chosen and not yet stored, priced the same way, across
  -- the whole workspace and before this call writes anything.
  select coalesce(sum(greatest(0, v.reported_comment_count
           - coalesce(stats.total, 0))), 0)::bigint
    into outstanding
    from public.video_selections s
    join public.videos v on v.workspace_id=w and v.id=s.video_id
    left join private.video_comment_stats stats
      on stats.workspace_id=w and stats.video_id=v.id
   where s.workspace_id=w and not (s.video_id = any(remove));

  -- A removal alone spends nothing and needs no plan: a paused tenant can still deselect.
  if cardinality(add) > 0 then
    remaining := private.analysis_remaining(w);
    if remaining is not null and estimate + outstanding > remaining then
      raise exception 'quota_exceeded' using errcode='53400'; end if;
  end if;

  delete from public.video_selections where workspace_id=w and video_id = any(remove);
  insert into public.video_selections(workspace_id, channel_id, video_id, selected_by)
  select w, c, x.id, (select auth.uid()) from unnest(add) x(id)
  on conflict (workspace_id, video_id) do nothing;

  -- Adopt comments and predictions from other workspaces for the newly selected videos
  if cardinality(add) > 0 then
    for rec in select x.id as video_id from unnest(add) x(id) loop
      perform private.adopt_video_comments_and_predictions(w, rec.video_id);
    end loop;
  end if;

  if cardinality(add) > 0 then
    select id into j from public.jobs
     where workspace_id=w and channel_id=c and type='collect' and status='running'
     order by created_at limit 1;
    if j is not null then
      running := true;
    else
      begin
        j := private.enqueue_sync_impl(w, c, 'selection-' || gen_random_uuid()::text);
        select status = 'running' into running from public.jobs where id = j;
        queued := not running;
      exception when sqlstate '53400' then
        deferred := true;
      end;
    end if;
  end if;

  return jsonb_build_object('job_id', j, 'queued', queued, 'deferred', deferred,
                            'already_running', running,
                            'estimate', estimate, 'unknown_count', unknowns,
                            'outstanding', outstanding,
                            'remaining_after', case when remaining is null then -1 else remaining - outstanding - estimate end);
end $function$

CREATE OR REPLACE FUNCTION private.set_workspace_topics_impl(w uuid, topics jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v int; begin
  if not private.has_role(w, array['workspace_owner']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  if topics is null or jsonb_typeof(topics) <> 'array' or jsonb_array_length(topics) = 0
     or jsonb_array_length(topics) > 50 then
    raise exception 'invalid_topics' using errcode='22023'; end if;
  if exists (select 1 from jsonb_array_elements(topics) t
              where jsonb_typeof(t) <> 'object'
                 or coalesce(t->>'key','') !~ '^[a-z][a-z0-9_]{0,39}$'
                 or length(coalesce(t->>'name_ar','')) not between 1 and 80
                 or length(coalesce(t->>'name_en','')) not between 1 and 80
                 or length(coalesce(t->>'description','')) not between 1 and 400) then
    raise exception 'invalid_topics' using errcode='22023'; end if;
  if (select count(distinct t->>'key') from jsonb_array_elements(topics) t)
     <> jsonb_array_length(topics) then
    raise exception 'invalid_topics' using errcode='22023'; end if;

  insert into public.workspace_topics(workspace_id, key, name_ar, name_en, description, position)
  select w, t->>'key', t->>'name_ar', t->>'name_en', t->>'description', ord
    from jsonb_array_elements(topics) with ordinality as x(t, ord)
  on conflict (workspace_id, key) do update set
    name_ar = excluded.name_ar, name_en = excluded.name_en,
    description = excluded.description, position = excluded.position,
    retired_at = null;
  update public.workspace_topics set retired_at = now()
   where workspace_id = w and retired_at is null
     and key not in (select t->>'key' from jsonb_array_elements(topics) t);

  update public.workspaces
     set topic_taxonomy_version = topic_taxonomy_version + 1, active_topic_key = null
   where id = w returning topic_taxonomy_version into v;
  return v;
end $function$

CREATE OR REPLACE FUNCTION private.submit_comment_review_impl(w uuid, c uuid, seen_hash text, verdict text, why text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r uuid; current_hash text; begin
 if not private.has_role(w,array['workspace_owner','analyst']) then raise exception 'forbidden' using errcode='42501'; end if;
 if verdict not in ('positive','negative','neutral','mixed') then raise exception 'invalid_label' using errcode='22023'; end if;
 if why is null or length(trim(why)) not between 1 and 500 then raise exception 'invalid_reason' using errcode='22023'; end if;
 select content_hash into current_hash from public.comments where workspace_id=w and id=c;
 if current_hash is null then raise exception 'invalid_comment' using errcode='23503'; end if;
 -- Optimistic concurrency on the text the reviewer actually read. If the comment
 -- was edited since, the verdict belongs to text that no longer exists.
 if current_hash is distinct from seen_hash then raise exception 'stale_comment_text' using errcode='40001'; end if;
 insert into public.comment_reviews(workspace_id,comment_id,content_hash,label,reviewer_id,reason,origin)
 values(w,c,current_hash,verdict,(select auth.uid()),trim(why),'human') returning id into r;
 return r;
end $function$

CREATE OR REPLACE FUNCTION private.submit_topic_review_impl(w uuid, c uuid, seen_hash text, topic text, why text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r uuid; current_hash text; begin
  if not private.has_role(w, array['workspace_owner','analyst']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  if not exists (select 1 from public.workspace_topics t
                  where t.workspace_id=w and t.key=topic and t.retired_at is null) then
    raise exception 'invalid_topic' using errcode='22023'; end if;
  if why is null or length(trim(why)) not between 1 and 500 then
    raise exception 'invalid_reason' using errcode='22023'; end if;
  select content_hash into current_hash from public.comments where workspace_id=w and id=c;
  if current_hash is null then raise exception 'invalid_comment' using errcode='23503'; end if;
  if current_hash is distinct from seen_hash then
    raise exception 'stale_comment_text' using errcode='40001'; end if;
  insert into public.topic_reviews(workspace_id,comment_id,content_hash,topic_key,reviewer_id,reason,origin)
  values (w, c, current_hash, topic, (select auth.uid()), trim(why), 'human') returning id into r;
  return r;
end $function$

CREATE OR REPLACE FUNCTION private.subscription_open(s subscriptions)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select (s.status = 'active'   and now() >= s.period_start and now() < s.period_end)
      or (s.status = 'past_due' and now() < s.period_end + interval '7 days')
$function$

CREATE OR REPLACE FUNCTION private.sync_purge_marker()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.text_raw is not null then new.content_purged_at := null; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.topic_classification_key(w uuid, model_id text, prompt_version text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select 'topics:v' || ws.topic_taxonomy_version::text || '+' || model_id || '+' || prompt_version
    from public.workspaces ws where ws.id = w
$function$

CREATE OR REPLACE FUNCTION private.topic_row_due(w uuid, cm comments, k text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select not exists (
    select 1 from public.topic_predictions p
     where p.workspace_id = w and p.comment_id = cm.id
       and p.content_hash = cm.content_hash and p.classification_key = k
       and p.status in ('succeeded','skipped','unsupported'))
$function$

CREATE OR REPLACE FUNCTION private.topic_units_remaining(w uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare sub record; begin
  select s.period_start, pl.topic_units into sub
    from public.subscriptions s join public.plans pl on pl.key = s.plan_key
   where s.workspace_id = private.billing_root(w) and private.subscription_open(s);
  if not found then return null; end if;
  if sub.topic_units is null or sub.topic_units >= 2147483647 then return null; end if;
  return greatest(0::bigint, sub.topic_units::bigint + private.granted_units(w, 'topic_classification')
                     - private.used_units(w, 'topic_classification', sub.period_start));
end $function$

CREATE OR REPLACE FUNCTION private.topics_pending(w uuid, c uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare active text; ver int; begin
  select active_topic_key, topic_taxonomy_version into active, ver from public.workspaces where id = w;
  return exists (
    select 1 from public.comments cm
      join public.videos v on v.workspace_id = w and v.id = cm.video_id
      join public.channels ch on ch.workspace_id = w and ch.id = v.channel_id
     where cm.workspace_id = w and v.channel_id = c
       and (cm.author_channel_id is null or cm.author_channel_id <> ch.external_channel_id)
       and (case when active is null
                 then not exists (select 1 from public.topic_predictions p
                                   where p.workspace_id = w and p.comment_id = cm.id
                                     and p.content_hash = cm.content_hash
                                     and p.status in ('succeeded','skipped','unsupported')
                                     and p.classification_key like 'topics:v' || ver::text || '+%')
                 else private.topic_row_due(w, cm, active) end)
     limit 1);
end $function$

CREATE OR REPLACE FUNCTION private.touch_worker_seen(token_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; begin
  w := private.worker_workspace(token_hash);
  if w is null then
    insert into public.worker_seen(workspace_id, last_seen_at)
    select ws.id, now() from public.workspaces ws
    on conflict (workspace_id) do update set last_seen_at = now();
  else
    insert into public.worker_seen(workspace_id, last_seen_at)
    values (w, now())
    on conflict (workspace_id) do update set last_seen_at = now();
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.unblock_due_jobs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare count int := 0; begin
  -- Cancel any blocked job that is already superseded by an active queued/running job
  update public.jobs b
     set status = 'cancelled',
         error_code = 'superseded_by_active_job'
   where b.status = 'blocked'
     and exists (
       select 1 from public.jobs a
        where a.workspace_id = b.workspace_id
          and a.channel_id = b.channel_id
          and a.type = b.type
          and a.status in ('queued', 'running')
          and a.id <> b.id
     );

  -- Unblock due jobs that have no outstanding active job without resetting attempt/reclaims
  update public.jobs j
     set status = 'queued',
         error_code = null,
         lease_token = null,
         lease_expires_at = null,
         not_before = now()
   where j.status = 'blocked'
     and j.not_before is not null
     and j.not_before <= now()
     and not exists (
       select 1 from public.jobs a
        where a.workspace_id = j.workspace_id
          and a.channel_id = j.channel_id
          and a.type = j.type
          and a.status in ('queued', 'running')
          and a.id <> j.id
     );
  get diagnostics count = row_count;
  return count;
end $function$

CREATE OR REPLACE FUNCTION private.usage_summary_impl(w uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not private.has_role(w) then raise exception 'forbidden' using errcode='42501'; end if;
 return private.usage_summary_unchecked(w);
end $function$

CREATE OR REPLACE FUNCTION private.usage_summary_unchecked(w uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sub record; pl public.plans; begin
 select s.* into sub from public.subscriptions s where s.workspace_id=private.billing_root(w);
 if not found then return null; end if;
 select * into pl from public.plans where key = sub.plan_key;
 return jsonb_build_object('plan_key',sub.plan_key,'status',sub.status,
 'period_start',to_jsonb(sub.period_start),'period_end',to_jsonb(sub.period_end),
 'cancel_at_period_end', sub.cancel_at_period_end, 'billing_interval', sub.billing_interval, 'provider', sub.provider,
 'plan', private.plan_json(pl),
 'budgets',jsonb_build_array(
 private.budget_entry('comment_analysis',pl.analysis_units,private.used_units(w,'comment_analysis',sub.period_start),private.granted_units(w,'comment_analysis')),
 private.budget_entry('historical_backfill',pl.backfill_units,private.used_units(w,'historical_backfill',sub.period_start),private.granted_units(w,'historical_backfill')),
 private.budget_entry('topic_classification',pl.topic_units,private.used_units(w,'topic_classification',sub.period_start),private.granted_units(w,'topic_classification'))));
end $function$

CREATE OR REPLACE FUNCTION private.used_units(w uuid, kind text, since timestamp with time zone)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(sum(u.units), 0)::bigint
    from public.usage_events u
   where u.event_type = used_units.kind and u.period_start = since
     and u.workspace_id in (select s.workspace_id from public.subscriptions s
                            where coalesce(s.billing_workspace_id, s.workspace_id) = private.billing_root(w));
$function$

CREATE OR REPLACE FUNCTION private.worker_channel_grant(token_hash text, j uuid)
 RETURNS TABLE(connection_id uuid, encrypted_tokens bytea, key_version text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; begin
  w := private.worker_workspace(token_hash);
  return query
  select c.id, c.encrypted_tokens, c.key_version
  from private.oauth_connections c
  join public.jobs jb on jb.channel_id = c.channel_id and jb.workspace_id = c.workspace_id
  where jb.id = j and (w is null or c.workspace_id = w) and c.status = 'connected'
  order by c.id desc limit 1;
  if not found then
    -- A job on a channel nobody has connected is not an error to retry: there
    -- is nothing to collect with until someone authorises it.
    raise exception 'channel_not_connected' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.worker_claim(token_hash text)
 RETURNS SETOF jobs
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  return query select * from private.claim_job(private.worker_workspace(token_hash));
end $function$

CREATE OR REPLACE FUNCTION private.worker_commit_batch(token_hash text, j uuid, t uuid, b text, hash text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform private.worker_job(token_hash, j, t);
  perform private.touch_worker_seen(token_hash);
  return private.commit_batch(j, t, b, hash, payload);
end $function$

CREATE OR REPLACE FUNCTION private.worker_commit_catalogue(token_hash text, j uuid, t uuid, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE w uuid; c uuid; c_platform text; n int; BEGIN
  w := private.worker_job(token_hash, j, t);
  SELECT channel_id INTO c FROM public.jobs WHERE id = j;
  SELECT coalesce(platform, 'youtube') INTO c_platform FROM public.channels WHERE id = c;
  IF payload IS NULL OR jsonb_typeof(payload) <> 'array' THEN
    RAISE EXCEPTION 'invalid_catalogue' USING errcode='22023'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(payload) i
     WHERE jsonb_typeof(i) <> 'object'
        OR (c_platform = 'youtube' AND coalesce(i->>'external_video_id','') !~ '^[A-Za-z0-9_-]{11}$')
        OR (c_platform <> 'youtube' AND (length(coalesce(i->>'external_video_id','')) NOT BETWEEN 1 AND 100 OR coalesce(i->>'external_video_id','') ~ '\s'))
        OR (c_platform = 'youtube' AND i ? 'kind' AND i->>'kind' NOT IN ('video','short','stream'))
        OR (c_platform <> 'youtube' AND i ? 'kind' AND i->>'kind' NOT IN ('video','short','stream','channel_post','tweet','status'))
        OR (i ? 'reported_comment_count'
            AND jsonb_typeof(i->'reported_comment_count') NOT IN ('number','null'))
        OR (i ? 'view_count'
            AND jsonb_typeof(i->'view_count') NOT IN ('number','null'))
        OR (i ? 'like_count'
            AND jsonb_typeof(i->'like_count') NOT IN ('number','null'))
        OR (i ? 'favorite_count'
            AND jsonb_typeof(i->'favorite_count') NOT IN ('number','null'))
        OR (i ? 'published_at' AND jsonb_typeof(i->'published_at') NOT IN ('string','null'))
        OR (i ? 'comments_state' AND i->>'comments_state' NOT IN ('open','disabled','unknown'))
        OR (i ? 'field_provenance' AND jsonb_typeof(i->'field_provenance') <> 'object')) THEN
    RAISE EXCEPTION 'invalid_catalogue' USING errcode='22023'; END IF;

  INSERT INTO public.videos(workspace_id, channel_id, platform, external_video_id, title, kind,
    published_at, duration_sec, thumbnail_url, reported_comment_count, comments_state,
    view_count, like_count, favorite_count, tags, description, category_id,
    catalogued_at, last_observed_at, field_provenance)
  SELECT w, c, c_platform, i->>'external_video_id',
         coalesce(nullif(i->>'title',''), i->>'external_video_id'),
         coalesce(i->>'kind', CASE WHEN c_platform='telegram' THEN 'channel_post' WHEN c_platform='x' THEN 'tweet' ELSE 'video' END),
         (i->>'published_at')::timestamptz,
         (i->>'duration_sec')::int,
         i->>'thumbnail_url',
         (i->>'reported_comment_count')::int,
         coalesce(
           nullif(i->>'comments_state', ''),
           CASE
             WHEN c_platform = 'youtube' THEN
               CASE WHEN jsonb_typeof(i->'reported_comment_count') = 'number' THEN 'open' ELSE 'disabled' END
             ELSE
               'open'
           END
         ),
         (i->>'view_count')::bigint,
         (i->>'like_count')::bigint,
         (i->>'favorite_count')::bigint,
         CASE WHEN i ? 'tags' AND jsonb_typeof(i->'tags') = 'array'
              THEN ARRAY(SELECT jsonb_array_elements_text(i->'tags'))
              ELSE '{}'::text[] END,
         i->>'description',
         i->>'category_id',
         now(), now(), coalesce(i->'field_provenance', '{}'::jsonb)
    FROM jsonb_array_elements(payload) i
  ON CONFLICT (workspace_id, platform, external_video_id) DO UPDATE SET
    title = CASE WHEN excluded.title <> excluded.external_video_id
                 THEN excluded.title ELSE public.videos.title END,
    kind = excluded.kind,
    published_at = coalesce(excluded.published_at, public.videos.published_at),
    duration_sec = coalesce(excluded.duration_sec, public.videos.duration_sec),
    thumbnail_url = coalesce(excluded.thumbnail_url, public.videos.thumbnail_url),
    reported_comment_count = excluded.reported_comment_count,
    view_count = coalesce(excluded.view_count, public.videos.view_count),
    like_count = coalesce(excluded.like_count, public.videos.like_count),
    favorite_count = coalesce(excluded.favorite_count, public.videos.favorite_count),
    tags = CASE WHEN excluded.tags <> '{}'::text[] THEN excluded.tags ELSE public.videos.tags END,
    description = coalesce(nullif(excluded.description, ''), public.videos.description),
    category_id = coalesce(excluded.category_id, public.videos.category_id),
    comments_state = CASE
                       WHEN excluded.comments_state IN ('open', 'disabled')
                         THEN excluded.comments_state
                       WHEN public.videos.comments_state IS NOT NULL
                         THEN public.videos.comments_state
                       ELSE 'open'
                     END,
    catalogued_at = now(), last_observed_at = now(),
    field_provenance = public.videos.field_provenance || excluded.field_provenance;
  GET DIAGNOSTICS n = row_count;

  UPDATE public.channels SET catalogued_at = now() WHERE workspace_id = w AND id = c;
  UPDATE public.sync_runs SET coverage_summary = jsonb_build_object(
      'videos_found', (SELECT count(*) FROM jsonb_array_elements(payload)),
      'by_kind', (SELECT coalesce(jsonb_object_agg(k, cnt), '{}'::jsonb)
                    FROM (SELECT coalesce(i->>'kind','video') k, count(*) cnt
                            FROM jsonb_array_elements(payload) i GROUP BY 1) x))
   WHERE workspace_id = w AND job_id = j;
  RETURN jsonb_build_object('videos', n);
END $function$

CREATE OR REPLACE FUNCTION private.worker_commit_topics(token_hash text, j uuid, t uuid, b text, records jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  w uuid; c uuid; p text; kind text; hash text; prior text; keys text[]; covered text[]; wanted int; n int; final int;
begin
  w := private.worker_job(token_hash, j, t);
  select channel_id, type into c, kind from public.jobs where id = j;
  if kind <> 'analyse' then raise exception 'invalid_job_type' using errcode='22023'; end if;
  select platform into p from public.channels where id = c and workspace_id = w;
  p := coalesce(p, 'youtube');
  if b is null or length(b) not between 1 and 200 then
    raise exception 'invalid_batch' using errcode='22023'; end if;
  if records is null or jsonb_typeof(records) <> 'array' then
    raise exception 'invalid_batch' using errcode='22023'; end if;
  if jsonb_array_length(records) > 500 then
    raise exception 'batch_too_large' using errcode='22023'; end if;

  if exists (
    select 1 from jsonb_array_elements(records) r
     where jsonb_typeof(r) <> 'object'
        or coalesce(r->>'external_comment_id','') = ''
        or coalesce(r->>'content_hash','') = ''
        or r->>'status' not in ('succeeded','skipped','failed','unsupported')
        or ((r->>'status' = 'succeeded') <> (r->>'topic_key' is not null))
        or (r ? 'confidence' and jsonb_typeof(r->'confidence') not in ('number','null'))
        or coalesce(r->>'model_id','') !~ '^[A-Za-z0-9._-]{1,80}$'
        or coalesce(r->>'prompt_version','') !~ '^[A-Za-z0-9._-]{1,20}$'
        or r->>'classification_key' is distinct from
           private.topic_classification_key(w, r->>'model_id', r->>'prompt_version')) then
    raise exception 'invalid_batch' using errcode='22023'; end if;
  if (select count(distinct r->>'external_comment_id') from jsonb_array_elements(records) r)
     <> jsonb_array_length(records) then
    raise exception 'invalid_batch' using errcode='22023'; end if;

  -- Every named comment is held for this workspace and channel's platform, and every named topic is live.
  if exists (
    select 1 from jsonb_array_elements(records) r
     where not exists (select 1 from public.comments cm where cm.workspace_id = w
                         and cm.platform = p and cm.external_comment_id = r->>'external_comment_id')) then
    raise exception 'invalid_batch' using errcode='22023'; end if;
  if exists (
    select 1 from jsonb_array_elements(records) r
     where r->>'topic_key' is not null
       and not exists (select 1 from public.workspace_topics tp where tp.workspace_id = w
                         and tp.key = r->>'topic_key' and tp.retired_at is null)) then
    raise exception 'invalid_batch' using errcode='22023'; end if;

  hash := encode(sha256(convert_to(records::text, 'UTF8')), 'hex');
  select payload_hash into prior from private.job_batches where job_id = j and batch_key = b;
  if found then
    if prior is distinct from hash then raise exception 'batch_conflict' using errcode='23505'; end if;
    return jsonb_build_object('replayed', true, 'stored', 0);
  end if;

  select coalesce(array_agg(distinct 'topics:' || p || ':' || (r->>'external_comment_id')), '{}')
    into keys from jsonb_array_elements(records) r where r->>'status' = 'succeeded';
  wanted := coalesce(array_length(keys, 1), 0);
  if wanted > 0 then
    covered := private.reserve_usage(w, 'topic_classification', keys);
    if coalesce(array_length(covered, 1), 0) <> wanted then
      raise exception 'quota_exceeded' using errcode='53400'; end if;
  end if;

  with written as (
    insert into public.topic_predictions(
      workspace_id, comment_id, content_hash, classification_key, status, topic_key,
      confidence, model_id, prompt_version, error_code)
    select w, cm.id, r.content_hash, r.classification_key, r.status, r.topic_key,
           r.confidence, r.model_id, r.prompt_version, r.error_code
      from jsonb_to_recordset(records) as r(
        external_comment_id text, content_hash text, classification_key text, status text,
        topic_key text, confidence numeric, model_id text, prompt_version text, error_code text)
      join public.comments cm on cm.workspace_id = w and cm.platform = p
       and cm.external_comment_id = r.external_comment_id
    on conflict (workspace_id, comment_id, content_hash, classification_key) do update set
      status = excluded.status, topic_key = excluded.topic_key, confidence = excluded.confidence,
      error_code = excluded.error_code, model_id = excluded.model_id,
      prompt_version = excluded.prompt_version, predicted_at = now()
    where public.topic_predictions.status = 'failed'
    returning status)
  select count(*)::int, count(*) filter (where status <> 'failed')::int
    into n, final from written;

  insert into private.job_batches(job_id, batch_key, checkpoint, payload_hash, outcome)
  values (j, b, '{}'::jsonb, hash, 'partial');

  update public.sync_runs set coverage_summary = coalesce(coverage_summary, '{}'::jsonb)
     || jsonb_build_object('topics_stored',
          coalesce((coverage_summary->>'topics_stored')::int, 0) + final)
   where workspace_id = w and job_id = j;
  return jsonb_build_object('replayed', false, 'stored', n);
end $function$

CREATE OR REPLACE FUNCTION private.worker_due_videos(token_hash text, j uuid, t uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; c uuid; kind text; begin
  w := private.worker_job(token_hash, j, t);
  select channel_id, type into c, kind from public.jobs where id = j;
  if kind <> 'collect' then raise exception 'invalid_job_type' using errcode='22023'; end if;
  return private.due_videos(w, c);
end $function$

CREATE OR REPLACE FUNCTION private.worker_finish(token_hash text, j uuid, t uuid, outcome text, reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  w uuid;
  ch uuid;
  start_time timestamptz;
  dur_sec integer;
  j_attempt integer;
  backoff_seconds integer;
  sub_reset timestamptz;
  blocked_not_before timestamptz;
begin
  perform private.worker_job(token_hash, j, t);
  if outcome not in ('succeeded','partial','failed','blocked','cancelled') then
    raise exception 'invalid_outcome' using errcode='22023'; end if;

  select created_at, attempt, workspace_id, channel_id
    into start_time, j_attempt, w, ch
    from public.jobs
   where id = j;
  dur_sec := greatest(1, round(extract(epoch from (now() - coalesce(start_time, now())))))::int;

  -- Exponential backoff retry lifecycle for transient failures on attempts 1 and 2
  if outcome in ('failed', 'partial') and coalesce(j_attempt, 1) < 3 then
    backoff_seconds := least(30 * (2 ^ coalesce(j_attempt, 1)), 600);

    update public.jobs
       set status = 'queued',
           not_before = now() + (backoff_seconds || ' seconds')::interval,
           lease_token = null,
           lease_expires_at = null,
           error_code = reason,
           last_error = coalesce(reason, public.jobs.last_error),
           counters = jsonb_set(
             coalesce(counters, '{}'::jsonb),
             '{duration_seconds}',
             to_jsonb(dur_sec)
           )
     where id = j;

    insert into public.sync_runs(workspace_id, channel_id, job_id, mode, source,
                                 status, ended_at, error_code)
    values (w, ch, j, 'collect', 'unknown', outcome, now(), reason)
    on conflict (workspace_id, job_id) do update
      set status = excluded.status,
          ended_at = excluded.ended_at,
          error_code = excluded.error_code;
    return;
  end if;

  -- On blocked, set not_before by reason (quota -> next reset; plan_inactive/source_access_denied -> not time-based)
  if outcome = 'blocked' then
    if reason ilike '%quota%' or reason in ('quota_exceeded', 'rate_limited') then
      select s.period_end into sub_reset
        from public.subscriptions s
       where s.workspace_id = private.billing_root(w);

      if sub_reset is not null and sub_reset > now() and sub_reset <= (now() + interval '366 days') then
        blocked_not_before := sub_reset;
      else
        blocked_not_before := (date_trunc('day', now() at time zone 'utc') + interval '1 day');
      end if;
    else
      -- plan_inactive, source_access_denied, and other non-quota reasons are not time-based
      blocked_not_before := null;
    end if;
  end if;

  update public.jobs set status = outcome,
    error_code = case
      when outcome = 'succeeded' then null
      when outcome in ('failed', 'partial') and coalesce(j_attempt, 1) >= 3 then 'retry_exhausted:' || coalesce(reason, 'unknown')
      else reason
    end,
    last_error = case
      when outcome = 'succeeded' then null
      when outcome in ('failed', 'partial') and coalesce(j_attempt, 1) >= 3 then 'retry_exhausted:' || coalesce(reason, 'unknown')
      else coalesce(reason, public.jobs.last_error)
    end,
    not_before = case
      when outcome = 'blocked' then blocked_not_before
      else public.jobs.not_before
    end,
    counters = jsonb_set(
      coalesce(counters, '{}'::jsonb),
      '{duration_seconds}',
      to_jsonb(dur_sec)
    ),
    lease_token = null, lease_expires_at = null
  where id = j;

  insert into public.sync_runs(workspace_id, channel_id, job_id, mode, source,
                               status, ended_at, error_code)
  values (w, ch, j, 'collect', 'unknown', outcome, now(),
          case
            when outcome = 'succeeded' then null
            when outcome in ('failed', 'partial') and coalesce(j_attempt, 1) >= 3 then 'retry_exhausted:' || coalesce(reason, 'unknown')
            else reason
          end)
  on conflict (workspace_id, job_id) do update
    set status = excluded.status,
        ended_at = excluded.ended_at,
        error_code = excluded.error_code;
end $function$

CREATE OR REPLACE FUNCTION private.worker_heartbeat(token_hash text, j uuid, t uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform private.worker_job(token_hash, j, t);
  perform private.heartbeat(j, t);
  perform private.touch_worker_seen(token_hash);
end $function$

CREATE OR REPLACE FUNCTION private.worker_job(token_hash text, j uuid, t uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; owner uuid; begin
  w := private.worker_workspace(token_hash);
  select workspace_id into owner from public.jobs
  where id = j and lease_token = t and status = 'running' and lease_expires_at > now();
  if owner is null then raise exception 'lease_lost' using errcode='40001'; end if;
  if w is not null and owner <> w then raise exception 'forbidden' using errcode='42501'; end if;
  return owner;
end $function$

CREATE OR REPLACE FUNCTION private.worker_mark_revoked(token_hash text, j uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; ch uuid; begin
  w := private.worker_workspace(token_hash);
  select channel_id into ch from public.jobs where id = j and (w is null or workspace_id = w);
  if ch is null then raise exception 'forbidden' using errcode='42501'; end if;
  perform private.oauth_mark_revoked(ch);
end $function$

CREATE OR REPLACE FUNCTION private.worker_reader_grant(token_hash text)
 RETURNS TABLE(connection_id uuid, encrypted_tokens bytea, key_version text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform private.worker_workspace(token_hash);
  -- connection_id here is the reader row's own id — the handle renewals and
  -- revocation write back to — not the connection the seal was copied from.
  return query select r.id, r.encrypted_tokens, r.key_version
    from private.platform_reader r
   where r.status = 'active' order by r.created_at desc limit 1;
end $function$

CREATE OR REPLACE FUNCTION private.worker_reader_revoked(token_hash text, connection uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform private.worker_workspace(token_hash);
  update private.platform_reader set status = 'retired', retired_at = now()
   where id = connection and status = 'active';
end $function$

CREATE OR REPLACE FUNCTION private.worker_renew_grant(token_hash text, j uuid, t uuid)
 RETURNS TABLE(connection_id uuid, encrypted_tokens bytea, key_version text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; begin
  -- The same lease check every worker call makes: live lease, owned job.
  w := private.worker_job(token_hash, j, t);
  return query
  select c.id, c.encrypted_tokens, c.key_version
  from private.oauth_connections c
  join public.jobs jb on jb.channel_id = c.channel_id and jb.workspace_id = c.workspace_id
  where jb.id = j and c.workspace_id = w and c.status = 'connected'
  order by c.id desc limit 1;
  if not found then
    -- Same answer the claim path gives: a channel with no usable grant is a
    -- fact about the channel, and the worker stops asking for tokens.
    raise exception 'channel_not_connected' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.worker_store_grant(token_hash text, connection uuid, tokens bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; begin
  w := private.worker_workspace(token_hash);
  update private.oauth_connections set encrypted_tokens = tokens
  where id = connection and (w is null or workspace_id = w) and status = 'connected';
  if not found then raise exception 'forbidden' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.worker_store_reader_grant(token_hash text, connection uuid, tokens bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform private.worker_workspace(token_hash);
  update private.platform_reader set encrypted_tokens = tokens
   where id = connection and status = 'active';
  if not found then raise exception 'forbidden' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.worker_tick(token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; ws uuid; r jsonb; d int := 0; k int := 0; a int := 0; n int := 0; begin
  w := private.worker_workspace(token_hash);
  if w is not null then return private.schedule_due_work(w); end if;
  for ws in select workspace_id from public.subscriptions where status = 'active' loop
    r := private.schedule_due_work(ws);
    d := d + coalesce((r->>'discover')::int, 0);
    k := k + coalesce((r->>'collect')::int, 0);
    a := a + coalesce((r->>'analyse')::int, 0);
    n := n + 1;
  end loop;
  return jsonb_build_object('discover', d, 'collect', k, 'analyse', a, 'workspaces', n);
end $function$

CREATE OR REPLACE FUNCTION private.worker_topics_due(token_hash text, j uuid, t uuid, model_id text, prompt_version text, max_rows integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  w uuid; c uuid; p text; kind text; k text; active text; rows jsonb; taxonomy jsonb;
  remaining bigint; sub_open boolean;
begin
  w := private.worker_job(token_hash, j, t);
  select channel_id, type into c, kind from public.jobs where id = j;
  if kind <> 'analyse' then raise exception 'invalid_job_type' using errcode='22023'; end if;
  select platform into p from public.channels where id = c and workspace_id = w;
  p := coalesce(p, 'youtube');
  if model_id !~ '^[A-Za-z0-9._-]{1,80}$' or prompt_version !~ '^[A-Za-z0-9._-]{1,20}$' then
    raise exception 'invalid_batch' using errcode='22023'; end if;
  k := private.topic_classification_key(w, model_id, prompt_version);
  select active_topic_key into active from public.workspaces where id = w;
  if active is not null and active <> k then
    return jsonb_build_object('classification_key', k, 'active', false,
                              'taxonomy', '[]'::jsonb, 'rows', '[]'::jsonb);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('key', tp.key, 'description', tp.description)
                            order by tp.position), '[]'::jsonb)
    into taxonomy
    from public.workspace_topics tp where tp.workspace_id = w and tp.retired_at is null;

  select private.subscription_open(s) into sub_open
    from public.subscriptions s
   where s.workspace_id = private.billing_root(w);
  sub_open := coalesce(sub_open, false);

  if sub_open then
    remaining := private.topic_units_remaining(w);
  else
    remaining := 0::bigint;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'external_comment_id', e.external_comment_id, 'content_hash', e.content_hash,
           'text', e.text, 'parent_text', e.parent_text, 'is_reply', e.is_reply)
           order by e.published_at nulls last, e.id), '[]'::jsonb)
    into rows
    from (
    select d.* from (
      select r.*,
             count(*) filter (where r.costs)
               over (order by r.published_at nulls last, r.id
                     rows between unbounded preceding and current row) as spent
        from (
          select cm.id, cm.published_at, cm.external_comment_id, cm.content_hash,
                 case when cm.content_purged_at is null then cm.text_raw end as text,
                 case when parent.content_purged_at is null then parent.text_raw end as parent_text,
                 cm.is_reply,
                 cm.content_purged_at is null and not exists (
                   select 1 from public.usage_events u
                    where u.workspace_id = w
                      and u.event_type = 'topic_classification'
                      and (u.event_key = 'topics:' || p || ':' || cm.external_comment_id
                           or (p = 'youtube' and u.event_key = 'topics:youtube:' || cm.external_comment_id))) as costs
            from public.comments cm
            join public.videos v on v.workspace_id = w and v.id = cm.video_id
            join public.channels ch on ch.workspace_id = w and ch.id = v.channel_id
            left join public.comments parent on parent.workspace_id = w
              and parent.platform = cm.platform and parent.external_comment_id = cm.external_parent_id
           where cm.workspace_id = w and v.channel_id = c
             and (cm.author_channel_id is null or cm.author_channel_id <> ch.external_channel_id)
             and private.topic_row_due(w, cm, k)
        ) r
    ) d
    where (sub_open and (remaining is null or not d.costs or d.spent <= remaining))
    order by d.published_at nulls last, d.id
    limit least(greatest(coalesce(max_rows, 200), 1), 200)
    ) e;

  if jsonb_array_length(rows) = 0 and (not sub_open or (remaining is not null and remaining = 0))
     and private.topics_pending(w, c) then
    return jsonb_build_object('classification_key', k, 'active', true,
                              'taxonomy', '[]'::jsonb, 'rows', '[]'::jsonb,
                              'blocked', 'quota_exceeded');
  end if;
  return jsonb_build_object('classification_key', k, 'active', true,
                            'taxonomy', taxonomy, 'rows', rows);
end $function$

CREATE OR REPLACE FUNCTION private.worker_video_counts(token_hash text, j uuid, t uuid, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; c uuid; iv int; updated int; unchanged int; begin
  w := private.worker_job(token_hash, j, t);
  select channel_id into c from public.jobs where id = j;
  if payload is null or jsonb_typeof(payload) <> 'array' then
    raise exception 'invalid_counts' using errcode='22023'; end if;
  if exists (
    select 1 from jsonb_array_elements(payload) i
     where jsonb_typeof(i) <> 'object'
        or coalesce(i->>'external_video_id','') !~ '^[A-Za-z0-9_-]{11}$'
        or not (i ? 'comment_count')
        or jsonb_typeof(i->'comment_count') not in ('number','null')
        -- A count is a whole, non-negative number. A fraction or a negative
        -- would otherwise fail the column check as a bare 23514.
        or (jsonb_typeof(i->'comment_count') = 'number'
            and (i->>'comment_count') !~ '^[0-9]+$')) then
    raise exception 'invalid_counts' using errcode='22023'; end if;

  -- The stored count follows the source; a null answer leaves the old value
  -- in place but still records that the source was asked. The last item wins
  -- when an id is repeated, as it would if the payload were applied in order.
  update public.videos v
     set reported_comment_count = coalesce(p.cnt, v.reported_comment_count),
         reported_comment_count_at = now()
    from (select distinct on (i->>'external_video_id')
                 i->>'external_video_id' as ext, (i->>'comment_count')::int as cnt
            from jsonb_array_elements(payload) with ordinality as x(i, ord)
           order by i->>'external_video_id', ord desc) p
   where v.workspace_id = w and v.channel_id = c and v.external_video_id = p.ext;
  get diagnostics updated = row_count;

  -- Deferred: selected, the source reported a count, and it is exactly the
  -- count the last exhausted read ended at. 'unchanged' is a deferral that
  -- followed such a read with no read since, so its last_seen still stands;
  -- comparing only after 'exhausted' would read every second check and
  -- halve the saving. A partial read never set last_seen, so it is never
  -- deferred; a null last_seen (never read) is never equal to anything.
  iv := coalesce(private.plan_limit(w, 'live_interval'), 1440);
  update public.video_selections s
     set next_check_at = now() + make_interval(mins => iv),
         last_outcome = 'unchanged'
    from public.videos v
    join (select distinct on (i->>'external_video_id')
                 i->>'external_video_id' as ext, (i->>'comment_count')::int as cnt
            from jsonb_array_elements(payload) with ordinality as x(i, ord)
           order by i->>'external_video_id', ord desc) p on p.ext = v.external_video_id
   where s.workspace_id = w and s.channel_id = c and s.video_id = v.id
     and v.workspace_id = w and v.channel_id = c
     and p.cnt is not null and s.last_seen_comment_count = p.cnt
     and s.last_outcome in ('exhausted', 'unchanged');
  get diagnostics unchanged = row_count;

  return jsonb_build_object(
    'read', coalesce((select jsonb_agg(d->'external_video_id')
                        from jsonb_array_elements(private.due_videos(w, c)) d), '[]'::jsonb),
    'unchanged', unchanged, 'updated', updated);
end $function$

CREATE OR REPLACE FUNCTION private.worker_video_finished(token_hash text, j uuid, t uuid, v uuid, outcome text, reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; iv int; begin
  w := private.worker_job(token_hash, j, t);
  if outcome not in ('exhausted','partial','blocked','failed') then
    raise exception 'invalid_outcome' using errcode='22023'; end if;
  if not exists(select 1 from public.videos where workspace_id = w and id = v) then
    raise exception 'invalid_video' using errcode='23503'; end if;
  iv := coalesce(private.plan_limit(w, 'live_interval'), 1440);
  if outcome = 'exhausted' then
    update public.video_selections
       set last_collected_at = now(), last_outcome = 'exhausted',
           next_check_at = now() + make_interval(mins => iv),
           last_seen_comment_count = (select reported_comment_count from public.videos
                                       where workspace_id = w and id = v)
     where workspace_id = w and video_id = v;
    update public.videos set comments_state = 'open' where workspace_id = w and id = v;
  elsif reason = 'comments_disabled' then
    update public.videos set comments_state = 'disabled' where workspace_id = w and id = v;
    update public.video_selections set last_outcome = 'comments_disabled'
     where workspace_id = w and video_id = v;
  else
    update public.video_selections set last_outcome = coalesce(reason, outcome)
     where workspace_id = w and video_id = v;
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.worker_workspace(token_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w uuid; matched boolean; begin
  update private.worker_credentials c set last_seen_at = now()
  where c.token_hash = worker_workspace.token_hash and c.status = 'active'
  returning c.workspace_id, true into w, matched;
  if matched is not true then raise exception 'invalid_worker_credential' using errcode='42501'; end if;
  return w;
end $function$

CREATE OR REPLACE FUNCTION private.workspace_ops_snapshot_impl(w uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  state jsonb;
  plan_summary jsonb;
  video_counts jsonb;
  cat_summary jsonb;
begin
  if not (coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role' or private.has_role(w)) then
    raise exception 'forbidden' using errcode='42501';
  end if;

  select jsonb_build_object(
    'worker', jsonb_build_object(
      'connected', coalesce(
        (select s.last_seen_at > now() - interval '3 minutes'
           from public.worker_seen s
          where s.workspace_id = w),
        (select max(s.last_seen_at) > now() - interval '3 minutes'
           from public.worker_seen s),
        (select count(*) > 0
           from public.jobs
          where status = 'running' and lease_expires_at > now()),
        false),
      'last_heartbeat_at', coalesce(
        (select s.last_seen_at from public.worker_seen s
          where s.workspace_id = w),
        (select max(s.last_seen_at) from public.worker_seen s),
        (select max(lease_expires_at) - interval '5 minutes'
           from public.jobs
          where status = 'running' and lease_expires_at > now())),
      'busy', coalesce((select count(*) > 0 from public.jobs j
                         where j.workspace_id = w
                           and j.status = 'running'
                           and j.lease_expires_at > now()), false)),
    'queued_jobs', (select count(*) from public.jobs j
                     where j.workspace_id=w and j.status='queued'),
    'last_run', (
      select jsonb_build_object(
        'started_at', s.started_at, 'ended_at', s.ended_at, 'status', s.status,
        'source', s.source, 'error_code', s.error_code,
        'coverage', jsonb_build_object(
          'videos_seen', coalesce((s.coverage_summary->>'videos_seen')::int, 0),
          'comments_collected', coalesce((s.coverage_summary->>'comments_collected')::int, 0),
          'complete', coalesce((s.coverage_summary->>'complete')::boolean, false)))
      from public.sync_runs s where s.workspace_id=w and s.mode = 'collect'
      order by s.started_at desc limit 1))
  into state;

  select private.usage_summary_impl(w) into plan_summary;

  select
    coalesce(json_agg(json_build_object(
      'id', v.id::text,
      'total', coalesce(s.total, 0),
      'analysed', coalesce(s.analysed, 0)
    )), '[]'::json)::jsonb,
    jsonb_build_object(
      'total_comments_collected', coalesce(sum(s.total), 0)::int,
      'total_comments_analysed', coalesce(sum(s.analysed), 0)::int,
      'videos_with_comments', count(s.video_id) filter (where s.total > 0)::int
    )
  into video_counts, cat_summary
  from public.videos v
  left join private.video_comment_stats s
    on s.workspace_id = v.workspace_id
   and s.video_id = v.id
  where v.workspace_id = w;

  return jsonb_build_object(
    'sync', state,
    'plan', plan_summary,
    'video_counts', coalesce(video_counts, '[]'::jsonb),
    'catalogue_summary', coalesce(cat_summary, jsonb_build_object(
      'total_comments_collected', 0,
      'total_comments_analysed', 0,
      'videos_with_comments', 0
    ))
  );
end $function$

CREATE OR REPLACE FUNCTION public.addon_catalogue()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'key', a.key, 'kind', a.kind, 'units', a.units,
    'price_cents', a.price_cents, 'provider_prices', a.provider_prices) order by a.key), '[]'::jsonb)
  from public.addon_prices a
$function$

CREATE OR REPLACE FUNCTION public.admin_audit(p_limit integer DEFAULT 100)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_platform_admin() then raise exception 'forbidden' using errcode='42501'; end if;
  if p_limit < 1 or p_limit > 500 then raise exception 'invalid_limit' using errcode='22023'; end if;
  return query
    select jsonb_build_object(
      'id', a.id, 'workspace_id', a.workspace_id, 'workspace_name', coalesce(w.name, 'Platform'),
      'actor_id', a.actor_id, 'actor_email', u.email,
      'action', a.action, 'target_type', a.target_type, 'target_id', a.target_id,
      'created_at', to_jsonb(a.created_at))
    from public.audit_events a
    left join public.workspaces w on w.id = a.workspace_id
    left join auth.users u on u.id = a.actor_id
    order by a.created_at desc
    limit p_limit;
end $function$

CREATE OR REPLACE FUNCTION public.admin_channels()
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_platform_admin() then raise exception 'forbidden' using errcode='42501'; end if;
  return query
    select jsonb_build_object(
      'id', c.id, 'workspace_id', c.workspace_id, 'workspace_name', w.name,
      'external_channel_id', c.external_channel_id,
      'handle', c.handle, 'title', c.title, 'status', c.status,
      'video_count', (
        select count(*)
        from public.videos v
        where v.workspace_id = c.workspace_id
          and v.channel_id = c.id),
      'comment_count', (
        select coalesce(sum(s.total), 0)
        from public.videos v
        left join private.video_comment_stats s
          on s.workspace_id = v.workspace_id
         and s.video_id = v.id
        where v.workspace_id = c.workspace_id
          and v.channel_id = c.id),
      'last_sync_at', to_jsonb(ls.started_at),
      'last_sync_status', ls.status, 'last_sync_error', ls.error_code,
      'last_collect_ok_at', to_jsonb(lc.collected_at))
    from public.channels c
    join public.workspaces w on w.id = c.workspace_id
    left join lateral (
      select sr.started_at, sr.status, sr.error_code
      from public.sync_runs sr
      where sr.channel_id = c.id
      order by sr.started_at desc
      limit 1) ls on true
    left join lateral (
      select coalesce(sr.ended_at, sr.started_at) as collected_at
      from public.sync_runs sr
      where sr.channel_id = c.id
        and sr.mode = 'collect'
        and sr.status in ('succeeded', 'partial')
      order by sr.started_at desc
      limit 1) lc on true
    order by w.created_at desc, c.external_channel_id;
end $function$

CREATE OR REPLACE FUNCTION public.admin_ops()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  overview jsonb;
  failed jsonb;
begin
  if not public.is_platform_admin() then raise exception 'forbidden' using errcode='42501'; end if;
  select jsonb_build_object(
    'workspaces', (select count(*) from public.workspaces),
    'channels', (select count(*) from public.channels),
    'comments_7d', (
      select count(*) from public.comments
      where first_seen_at >= now() - interval '7 days'),
    'worker_fresh', coalesce((
      select max(last_seen_at) >= now() - interval '3 minutes'
      from public.worker_seen), false),
    'worker_last_seen', to_jsonb((select max(last_seen_at) from public.worker_seen)),
    'jobs_open', (
      select count(*) from public.jobs where status in ('queued','running')),
    'sync_runs_7d', (
      select count(*) from public.sync_runs
      where started_at >= now() - interval '7 days'),
    'sync_failed_7d', (
      select count(*) from public.sync_runs
      where started_at >= now() - interval '7 days'
        and status in ('failed','partial')))
  into overview;
  select coalesce(jsonb_agg(jsonb_build_object(
      'workspace_id', j.workspace_id, 'workspace_name', w.name,
      'channel_id', j.channel_id, 'handle', c.handle,
      'mode', j.mode, 'source', j.source,
      'started_at', to_jsonb(j.started_at), 'ended_at', to_jsonb(j.ended_at),
      'status', j.status, 'error_code', j.error_code)
    order by j.started_at desc), '[]'::jsonb)
  into failed
  from (
    select sr.workspace_id, sr.channel_id, sr.mode, sr.source,
           sr.started_at, sr.ended_at, sr.status, sr.error_code
    from public.sync_runs sr
    where sr.status in ('failed','partial')
      and sr.started_at >= now() - interval '14 days'
    order by sr.started_at desc
    limit 25
  ) j
  join public.workspaces w on w.id = j.workspace_id
  left join public.channels c on c.id = j.channel_id;
  return overview || jsonb_build_object('failed_runs', failed);
end $function$

CREATE OR REPLACE FUNCTION public.admin_plan_catalogue()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_platform_admin() then raise exception 'forbidden' using errcode='42501'; end if;
  return (select coalesce(jsonb_agg(private.plan_json(p) order by p.sort_order), '[]'::jsonb)
            from public.plans p);
end $function$

CREATE OR REPLACE FUNCTION public.admin_services_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  report jsonb;
  v_worker_last_seen timestamptz;
  v_worker_fresh boolean;
  v_db_size_mb bigint;
  v_active_conn int;
  v_jobs_queued int;
  v_jobs_running int;
  v_sync_24h int;
  v_failed_24h int;
  v_yt_runs_24h int;
  v_active_subs int;
  v_platforms jsonb;
  v_billing_webhooks jsonb;
begin
  if not public.is_platform_admin() then
    raise exception 'forbidden' using errcode='42501';
  end if;

  select max(last_seen_at) into v_worker_last_seen from public.worker_seen;
  v_worker_fresh := coalesce(v_worker_last_seen >= now() - interval '3 minutes', false);

  select coalesce(round(pg_database_size(current_database()) / (1024 * 1024)), 0) into v_db_size_mb;
  select count(*) into v_active_conn from pg_stat_activity where datname = current_database();

  select count(*) into v_jobs_queued from public.jobs where status = 'queued';
  select count(*) into v_jobs_running from public.jobs where status = 'running';

  select count(*) into v_sync_24h from public.sync_runs where started_at >= now() - interval '24 hours';
  select count(*) into v_failed_24h from public.sync_runs where started_at >= now() - interval '24 hours' and status in ('failed', 'partial');
  select count(*) into v_yt_runs_24h
  from public.sync_runs sr
  join public.channels c
    on c.workspace_id = sr.workspace_id and c.id = sr.channel_id
  where sr.started_at >= now() - interval '24 hours'
    and c.platform = 'youtube';

  with platform_names(platform) as (
    values ('youtube'::text), ('telegram'::text), ('x'::text), ('tiktok'::text)
  ), eligible as materialized (
    select sr.id, c.platform, sr.status, sr.started_at, sr.ended_at, sr.error_code
    from public.sync_runs sr
    join public.channels c
      on c.workspace_id = sr.workspace_id and c.id = sr.channel_id
    where sr.mode in ('discover', 'collect')
      and sr.status <> 'running'
      and sr.started_at >= now() - interval '7 days'
      and c.platform in ('youtube', 'telegram', 'x', 'tiktok')
  ), platform_health as (
    select p.platform, jsonb_build_object(
      'last_status', (
        select e.status from eligible e where e.platform = p.platform
        order by e.ended_at desc, e.started_at desc, e.id desc limit 1
      ),
      'last_finished_at', (
        select e.ended_at from eligible e where e.platform = p.platform
        order by e.ended_at desc, e.started_at desc, e.id desc limit 1
      ),
      'last_success_at', (
        select max(e.ended_at) from eligible e
        where e.platform = p.platform and e.status = 'succeeded'
      ),
      'last_failure_at', (
        select e.ended_at from eligible e
        where e.platform = p.platform and e.status in ('failed', 'blocked')
        order by e.ended_at desc, e.started_at desc, e.id desc limit 1
      ),
      'last_error_code', (
        select e.error_code from eligible e
        where e.platform = p.platform and e.status in ('failed', 'blocked')
        order by e.ended_at desc, e.started_at desc, e.id desc limit 1
      ),
      'runs_24h', (
        select count(*) from eligible e
        where e.platform = p.platform and e.started_at >= now() - interval '24 hours'
      ),
      'failures_24h', (
        select count(*) from eligible e
        where e.platform = p.platform
          and e.started_at >= now() - interval '24 hours'
          and e.status in ('failed', 'blocked', 'partial')
      ),
      'consecutive_failures', least(10, (
        select count(*) from eligible e
        where e.platform = p.platform
          and e.status in ('failed', 'blocked')
          and e.started_at > coalesce((
            select max(s.started_at) from eligible s
            where s.platform = p.platform and s.status = 'succeeded'
          ), '-infinity'::timestamptz)
      ))
    ) as health
    from platform_names p
  )
  select jsonb_object_agg(platform, health) into v_platforms from platform_health;

  select jsonb_build_object(
    'last_received_at', max(be.applied_at),
    'last_outcome', (
      select latest.outcome from private.billing_events latest
      order by latest.applied_at desc, latest.event_id desc limit 1
    ),
    'received_24h', count(*) filter (where be.applied_at >= now() - interval '24 hours'),
    'problems_7d', count(*) filter (
      where be.applied_at >= now() - interval '7 days'
        and be.outcome in ('unmapped', 'conflict')
    )
  ) into v_billing_webhooks
  from private.billing_events be;

  select count(*) into v_active_subs from public.subscriptions where status in ('active', 'trialing');

  select jsonb_build_object(
    'checked_at', to_jsonb(now()),
    'database', jsonb_build_object(
      'status', 'healthy',
      'size_mb', v_db_size_mb,
      'active_connections', v_active_conn,
      'rls_enforced', true
    ),
    'worker', jsonb_build_object(
      'fresh', v_worker_fresh,
      'last_seen_at', to_jsonb(v_worker_last_seen),
      'jobs_queued', v_jobs_queued,
      'jobs_running', v_jobs_running
    ),
    'sync_24h', jsonb_build_object(
      'total_runs', v_sync_24h,
      'failed_runs', v_failed_24h,
      'youtube_runs', v_yt_runs_24h
    ),
    'billing', jsonb_build_object(
      'active_subscriptions', v_active_subs
    ),
    'platforms', v_platforms,
    'billing_webhooks', v_billing_webhooks
  ) into report;

  return report;
end $function$

CREATE OR REPLACE FUNCTION public.admin_start_impersonation(p_target_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user record;
  v_ws_id uuid;
begin
  if not public.is_platform_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_target_user_id = auth.uid() then
    raise exception 'cannot_impersonate_self' using errcode = '22023';
  end if;

  select id, email into v_user
  from auth.users
  where id = p_target_user_id;

  if not found then
    raise exception 'user_not_found' using errcode = 'P0002';
  end if;

  -- Pick target user's first workspace if any (optional)
  select workspace_id into v_ws_id
  from public.memberships
  where user_id = p_target_user_id
  limit 1;

  insert into public.audit_events (workspace_id, actor_id, action, target_type, target_id)
  values (v_ws_id, auth.uid(), 'impersonation_started', 'user', p_target_user_id::text);

  return jsonb_build_object(
    'target_user_id', v_user.id,
    'target_email', v_user.email,
    'started_at', now()
  );
end $function$

CREATE OR REPLACE FUNCTION public.admin_stop_impersonation(p_target_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ws_id uuid;
begin
  if not public.is_platform_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select workspace_id into v_ws_id
  from public.memberships
  where user_id = p_target_user_id
  limit 1;

  insert into public.audit_events (workspace_id, actor_id, action, target_type, target_id)
  values (v_ws_id, auth.uid(), 'impersonation_ended', 'user', p_target_user_id::text);

  return jsonb_build_object('ok', true);
end $function$

CREATE OR REPLACE FUNCTION public.admin_users()
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_platform_admin() then raise exception 'forbidden' using errcode='42501'; end if;
  return query
    select jsonb_build_object(
      'id', u.id, 'email', u.email,
      'created_at', to_jsonb(u.created_at), 'last_sign_in_at', to_jsonb(u.last_sign_in_at),
      'workspace_count', count(m.workspace_id),
      'owner_count', count(m.workspace_id) filter (where m.role = 'workspace_owner'))
    from auth.users u
    left join public.memberships m on m.user_id = u.id
    group by u.id
    order by u.created_at desc;
end $function$

CREATE OR REPLACE FUNCTION public.admin_workspace_footprint(w uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_platform_admin() then raise exception 'forbidden' using errcode='42501'; end if;
  return jsonb_build_object(
    'channels',    (select count(*) from public.channels where workspace_id = w),
    'videos',      (select count(*) from public.videos where workspace_id = w),
    'comments',    (select count(*) from public.comments where workspace_id = w),
    'predictions', (select count(*) from public.sentiment_predictions where workspace_id = w)
                 + (select count(*) from public.topic_predictions where workspace_id = w),
    'reviews',     (select count(*) from public.comment_reviews where workspace_id = w)
                 + (select count(*) from public.topic_reviews where workspace_id = w),
    'members',     (select count(*) from public.memberships where workspace_id = w));
end $function$

