CREATE OR REPLACE FUNCTION public.request_historical_platform_sync(w uuid, p_channel_id uuid, p_days_back integer DEFAULT NULL::integer, p_max_items integer DEFAULT 500, p_published_after timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  calc_since timestamptz;
BEGIN
  IF p_published_after IS NOT NULL THEN
    calc_since := p_published_after;
  ELSIF p_days_back IS NOT NULL AND p_days_back > 0 THEN
    calc_since := now() - (p_days_back || ' days')::interval;
  ELSE
    calc_since := now() - interval '30 days';
  END IF;

  RETURN public.request_historical_platform_sync(
    w => w,
    c => p_channel_id,
    since_date => calc_since,
    max_items => coalesce(p_max_items, 500)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.request_historical_platform_sync(w uuid, c uuid, since_date timestamp with time zone DEFAULT NULL::timestamp with time zone, max_items integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  sub record;
  effective_since timestamptz;
  job_id uuid;
  existing_status text;
BEGIN
  IF NOT private.has_role(w, ARRAY['workspace_owner', 'analyst']) THEN
    RAISE EXCEPTION 'forbidden' USING errcode = '42501';
  END IF;

  PERFORM 1 FROM public.channels WHERE id = c AND workspace_id = w;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'channel_not_found' USING errcode = '22023';
  END IF;

  SELECT pl.key, pl.backfill_units, pl.historical_days_limit INTO sub
    FROM public.subscriptions s JOIN public.plans pl ON pl.key = s.plan_key
   WHERE s.workspace_id = private.billing_root(w) AND private.subscription_open(s);
  IF NOT FOUND THEN RAISE EXCEPTION 'no_active_plan' USING errcode = '53400'; END IF;

  -- Only block if explicitly set to 0 (e.g. Free tier). NULL means unlimited (Owner / Enterprise).
  IF sub.historical_days_limit IS NOT NULL AND sub.historical_days_limit = 0 THEN
    RAISE EXCEPTION 'historical_sync_not_allowed_on_plan' USING errcode = '53400';
  END IF;

  effective_since := coalesce(since_date, now() - interval '30 days');

  IF sub.historical_days_limit IS NOT NULL AND sub.historical_days_limit > 0 THEN
    IF effective_since < (now() - (sub.historical_days_limit || ' days')::interval) THEN
      RAISE EXCEPTION 'date_beyond_plan_limit' USING errcode = '22023';
    END IF;
  END IF;

  -- Guard against quota exceeded when limit is bounded
  IF private.backfill_remaining(w) IS NOT NULL AND private.backfill_remaining(w) <= 0 THEN
    RAISE EXCEPTION 'quota_exceeded' USING errcode = '53400';
  END IF;

  INSERT INTO public.jobs(workspace_id, channel_id, type, dedupe_key, checkpoint)
  VALUES (w, c, 'import', 'hist_sync:' || c || ':' || extract(epoch FROM effective_since), jsonb_build_object(
    'is_historical', true,
    'since', effective_since,
    'max_items', coalesce(max_items, 500),
    'source', 'platform_sync'
  ))
  ON CONFLICT (workspace_id, dedupe_key) DO UPDATE SET
    checkpoint = excluded.checkpoint, status = 'queued', attempt = 0, not_before = now()
  WHERE public.jobs.status NOT IN ('running', 'succeeded')
  RETURNING id INTO job_id;

  IF job_id IS NULL THEN
    SELECT id, status INTO job_id, existing_status
      FROM public.jobs
     WHERE workspace_id = w
       AND dedupe_key = 'hist_sync:' || c || ':' || extract(epoch FROM effective_since);
  ELSE
    existing_status := 'queued';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', job_id,
    'status', coalesce(existing_status, 'queued'),
    'historical_days_limit', sub.historical_days_limit,
    'backfill_remaining', private.backfill_remaining(w)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.retire_workspace(w uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid; keeper uuid; keeper_home uuid; ch record; begin
  me := auth.uid();
  if not private.has_role(w, array['workspace_owner']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  keeper := private.platform_owner();
  if keeper is null then raise exception 'no_platform_owner' using errcode='55000'; end if;
  -- The owner has nobody to hand a workspace to but themself.
  if me = keeper then raise exception 'owner_cannot_retire' using errcode='55000'; end if;
  -- A person always keeps one workspace to stand in; the product has no
  -- signed-in state without one.
  if (select count(*) from public.memberships m
       where m.user_id = me and m.role = 'workspace_owner') <= 1 then
    raise exception 'last_workspace' using errcode='55000'; end if;
  keeper_home := private.owner_plan_workspace(keeper);

  -- The grant leaves with the person who gave it; scheduled work stops.
  for ch in select id from public.channels where workspace_id = w loop
    update public.channels set status = 'disconnected' where id = ch.id;
    update private.oauth_connections set status = 'revoked' where channel_id = ch.id;
    update public.jobs set status = 'cancelled', error_code = 'disconnected'
     where channel_id = ch.id and status in ('queued','running');
  end loop;

  -- Membership moves whole: everyone out, the keeper in as owner.
  delete from public.memberships where workspace_id = w;
  insert into public.memberships(workspace_id, user_id, role) values (w, keeper, 'workspace_owner');

  -- Billing follows the keeper's root; the rows stay where they are.
  update public.subscriptions s
     set plan_key = k.plan_key, status = k.status, period_start = k.period_start,
         period_end = k.period_end, provider = k.provider, provider_ref = k.provider_ref,
         provider_customer_ref = k.provider_customer_ref, billing_interval = k.billing_interval,
         cancel_at_period_end = false, billing_workspace_id = keeper_home
    from public.subscriptions k
   where s.workspace_id = w and k.workspace_id = keeper_home;

  update public.workspaces
     set created_by = keeper, retired_from = me, retired_at = now()
   where id = w;
  insert into public.audit_events(workspace_id, actor_id, action, target_type, target_id)
  values (w, me, 'workspace_retired', 'workspace', me::text);
end $function$

